import{_ as o,a0 as l,w as s,s as r,ao as m,I as p,x as n,a1 as t,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Cinnamon 2.8 新變化一覽 | LCTT x X-CMD","titleTemplate":false,"description":"Cinnamon 2.8 新變化一覽 | LCTT (201602) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Cinnamon 2.8 新變化一覽 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Cinnamon 2.8 新變化一覽 | LCTT (201602) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201602/20151201 Cinnamon 2.8 Review","title":"Cinnamon 2.8 新變化一覽","tag":"201602","desc":""},"relativePath":"201602/20151201 Cinnamon 2.8 Review.md","filePath":"[post].md"}'),h={name:"201602/20151201 Cinnamon 2.8 Review.md"};function d(u,a,w,c,C,f){const e=l("Link");return s(),r("div",null,[a[13]||(a[13]=m(`<h1 id="cinnamon-2-8-新變化一覽" tabindex="-1">Cinnamon 2.8 新變化一覽 <a class="header-anchor" href="#cinnamon-2-8-新變化一覽" aria-label="Permalink to “Cinnamon 2.8 新變化一覽”">​</a></h1><p><img src="https://www.maketecheasier.com/assets/uploads/2015/11/cinnamon-2-8-featured.jpg" alt=""></p><p>除了Gnome和KDE外，Cinnamon是另一個很多人使用的桌面環境。它是由創作Linux Mint的團隊製作的，並且可以被安裝在許多其他發行版上。該桌面環境的最新版本 - Cinnamon 2.8 - 於去年底發佈，此版本修復了許多的Bug、做了許多改進並添加了一些新功能。</p><p>我將仔細介紹該發行版本的主要改進，以及如何更新到Cinnamon 2.8或者第一次安裝它。</p><h3 id="對applets的改進" tabindex="-1">對Applets的改進 <a class="header-anchor" href="#對applets的改進" aria-label="Permalink to “對Applets的改進”">​</a></h3><p>在此版本中，對面板中已有的Applets做了若干的改進。</p><h4 id="聲音-applet" tabindex="-1">聲音 Applet <a class="header-anchor" href="#聲音-applet" aria-label="Permalink to “聲音 Applet”">​</a></h4><p><img src="https://www.maketecheasier.com/assets/uploads/2015/11/rsz_cinnamon-28-sound-applet.jpg" alt="cinnamon-28-sound-applet"></p><p>聲音Applet經過修正，目前可以顯示音軌信息並且可以在音頻文件的藝術家封面上面進行媒體控制。對於支持拖動的音樂播放器來説（例如Banshee），會有一個進度條顯示同樣的播放進度，您可以用它來改變音軌位置。在applet的面板上右擊將顯示對輸入和輸出設備靜音的選項。</p><h4 id="電源-applet" tabindex="-1">電源 Applet <a class="header-anchor" href="#電源-applet" aria-label="Permalink to “電源 Applet”">​</a></h4><p>電源applet則會使用電池製造商的數據而不是通用名稱來顯示每一個連接的電池和設備。</p><h4 id="窗口縮略圖" tabindex="-1">窗口縮略圖 <a class="header-anchor" href="#窗口縮略圖" aria-label="Permalink to “窗口縮略圖”">​</a></h4><p><img src="https://www.maketecheasier.com/assets/uploads/2015/11/cinnamon-2.8-window-thumbnails.png" alt="cinnamon-2.8-window-thumbnails"></p><p>在Cinnamon 2.8中，可以在鼠標懸停於面板裏窗口列表時展示窗口縮略圖。如果您不喜歡該功能，您還可以關閉該選項。</p><h4 id="工作區切換-applet" tabindex="-1">工作區切換 Applet <a class="header-anchor" href="#工作區切換-applet" aria-label="Permalink to “工作區切換 Applet”">​</a></h4><p><img src="https://www.maketecheasier.com/assets/uploads/2015/11/cinnamon-2.8-workspace-switcher.png" alt="cinnamon-2.8-workspace-switcher"></p><p>添加工作區切換applet到您的面板將為您顯示一個代表該工作區的可視化圖像，一些矩形嵌套顯示在其中，代表您的窗口的位置。</p><h4 id="系統托盤" tabindex="-1">系統托盤 <a class="header-anchor" href="#系統托盤" aria-label="Permalink to “系統托盤”">​</a></h4><p>Cinnamon 2.8支持在系統托盤中顯示應用程序指示器。您可以很容易地在設置中禁用它，這將強制應用程序到以前使用狀態圖標的方式。</p><h3 id="視覺改進" tabindex="-1">視覺改進 <a class="header-anchor" href="#視覺改進" aria-label="Permalink to “視覺改進”">​</a></h3><p>Cinnamon 2.8還做了很多視覺上的改進。經典的切換器和Alt + Tab預覽切換器都被精細打磨，有了顯著的改進，同時修復了Alt + F2對話框的bug，並賦予了它更好的命令自動補全功能。</p><p>而且，傳統的最小化窗口時動畫效果的問題現已被解決，並可用於多個面板。</p><h3 id="nemo-的改進" tabindex="-1">Nemo 的改進 <a class="header-anchor" href="#nemo-的改進" aria-label="Permalink to “Nemo 的改進”">​</a></h3><p><img src="https://www.maketecheasier.com/assets/uploads/2015/11/rsz_cinnamon-28-nemo.jpg" alt="cinnamon-2.8-nemo"></p><p>Cinnamon默認的文件管理器也修復了一些bug，並有了新的“快速重命名”的功能，用於重命名文件和文件夾。可以通過兩次點擊文件或文件夾並在兩次點擊之間進行簡短的停頓以重命名文件。</p><p>Nemo也會自動地檢測縮略圖存在的問題，並提示您快速地修復它們。</p><h3 id="其他值得注意的改進" tabindex="-1">其他值得注意的改進 <a class="header-anchor" href="#其他值得注意的改進" aria-label="Permalink to “其他值得注意的改進”">​</a></h3><ul><li>Applets如今會在它們被更新的時候自動地重新加載一次。</li><li>對於多個監視器的支持有了顯著的提高。</li><li>對話框窗口有了改進，並且會附加到它的父窗口上。</li><li>HiDPI檢測有了改進。</li><li>QT5應用程序現在看起來更加原生並使用了默認的GTK主題。</li><li>窗口管理和渲染性能有了提升。</li><li>修復了許多bug。</li></ul><h3 id="如何獲得-cinnamon-2-8" tabindex="-1">如何獲得 Cinnamon 2.8 <a class="header-anchor" href="#如何獲得-cinnamon-2-8" aria-label="Permalink to “如何獲得 Cinnamon 2.8”">​</a></h3><p>如果您在運行Linux Mint，您會在更新Linux Mint 17.3 “Rosa”Cinnamon版本的時候獲得Cinnamon 2.8的更新。BETA版本現在已經放出，因此，如果您想立刻嘗試新的軟件，您可以試試。</p><p>對於Arch的用户來説，Cinnamon 2.8已經在Arch的官方倉庫了，您可以通過更新軟件包和系統級的更新獲得Cinnamon的最新版本。</p><p>最後，對於Ubuntu用户來説，您可以通過下面的命令安裝或更新Cinnamon 2.8：</p><pre><code>sudo add-apt-repository -y ppa:moorkai/cinnamon
sudo apt-get update
sudo apt-get install cinnamon
</code></pre><p>您已經嘗試了Cinnamon 2.8了麼？感覺如何呢？</p><hr>`,35)),p("p",null,[a[1]||(a[1]=n("via: ",-1)),t(e,{href:"https://www.maketecheasier.com/cinnamon-2-8-review/"},{default:i(()=>[...a[0]||(a[0]=[n("https://www.maketecheasier.com/cinnamon-2-8-review/",-1)])]),_:1})]),p("p",null,[a[5]||(a[5]=n("作者：",-1)),t(e,{href:"https://www.maketecheasier.com/author/ayoisaiah/"},{default:i(()=>[...a[2]||(a[2]=[n("Ayo Isaiah",-1)])]),_:1}),a[6]||(a[6]=n(" 譯者：",-1)),t(e,{href:"https://github.com/wwy-hust"},{default:i(()=>[...a[3]||(a[3]=[n("wwy-hust",-1)])]),_:1}),a[7]||(a[7]=n(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:i(()=>[...a[4]||(a[4]=[n("wxy",-1)])]),_:1})]),p("p",null,[a[10]||(a[10]=n("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[8]||(a[8]=[n("LCTT",-1)])]),_:1}),a[11]||(a[11]=n(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:i(()=>[...a[9]||(a[9]=[n("Linux中國",-1)])]),_:1}),a[12]||(a[12]=n(" 榮譽推出",-1))])])}const k=o(h,[["render",d]]);export{T as __pageData,k as default};
